"""
Phase A: Probe MI355X runner for hiprtc / hip-python availability.

This submission probes the runtime environment to determine which paths
are available for HIP runtime compilation:
  1. hip-python package (from hip import hip, hiprtc)
  2. ctypes libhiprtc.so / libamdhip64.so
  3. hipcc compiler subprocess
  4. torch CUDA arch list

Falls back to ref_kernel for correctness — the probe is about diagnostics.
Submit with: popcorn-cli --mode test
"""
import ctypes
import os
import shutil
import subprocess
import sys
import torch
from task import input_t, output_t

# Import reference kernel components for fallback
from reference import ref_kernel


def _probe_hip_python() -> dict:
    """Test hip-python package availability."""
    result = {"available": False, "version": None, "error": None}
    try:
        from hip import hip as hip_mod
        from hip import hiprtc as hiprtc_mod
        result["available"] = True
        # Try getting version
        try:
            ver = hip_mod.hipRuntimeGetVersion()
            result["version"] = str(ver)
        except Exception as e:
            result["version"] = f"unknown ({e})"
    except ImportError as e:
        result["error"] = str(e)
    except Exception as e:
        result["error"] = f"unexpected: {e}"
    return result


def _probe_ctypes_hiprtc() -> dict:
    """Test ctypes access to libhiprtc.so and libamdhip64.so."""
    result = {
        "hiprtc_available": False,
        "amdhip64_available": False,
        "hiprtc_path": None,
        "amdhip64_path": None,
        "error": None,
        "compile_test": None,
    }

    # Try loading libhiprtc.so
    for lib_name in ["libhiprtc.so", "libhiprtc.so.6", "libhiprtc.so.5"]:
        try:
            lib = ctypes.CDLL(lib_name)
            result["hiprtc_available"] = True
            result["hiprtc_path"] = lib_name
            break
        except OSError:
            continue

    # Try loading libamdhip64.so
    for lib_name in ["libamdhip64.so", "libamdhip64.so.6", "libamdhip64.so.5"]:
        try:
            lib = ctypes.CDLL(lib_name)
            result["amdhip64_available"] = True
            result["amdhip64_path"] = lib_name
            break
        except OSError:
            continue

    # Try a minimal compile if both libs available
    if result["hiprtc_available"] and result["amdhip64_available"]:
        try:
            hiprtc = ctypes.CDLL(result["hiprtc_path"])
            test_source = b'extern "C" __global__ void noop() {}'

            prog = ctypes.c_void_p()
            rc = hiprtc.hiprtcCreateProgram(
                ctypes.byref(prog),
                test_source, b"test.hip",
                0, None, None,
            )
            if rc == 0:
                opts = [b"--gpu-architecture=gfx950"]
                opts_arr = (ctypes.c_char_p * 1)(*opts)
                rc = hiprtc.hiprtcCompileProgram(prog, 1, opts_arr)
                if rc == 0:
                    result["compile_test"] = "SUCCESS: noop kernel compiled for gfx950"
                else:
                    # Get compile log
                    log_size = ctypes.c_size_t()
                    hiprtc.hiprtcGetProgramLogSize(prog, ctypes.byref(log_size))
                    log = ctypes.create_string_buffer(log_size.value)
                    hiprtc.hiprtcGetProgramLog(prog, log)
                    result["compile_test"] = f"COMPILE_FAIL (rc={rc}): {log.value.decode()}"
                hiprtc.hiprtcDestroyProgram(ctypes.byref(prog))
            else:
                result["compile_test"] = f"CREATE_FAIL (rc={rc})"
        except Exception as e:
            result["compile_test"] = f"ERROR: {e}"

    return result


def _probe_hipcc() -> dict:
    """Test hipcc compiler availability."""
    result = {"available": False, "version": None, "path": None, "error": None}
    hipcc = shutil.which("hipcc")
    if hipcc:
        result["available"] = True
        result["path"] = hipcc
        try:
            ver = subprocess.run(
                [hipcc, "--version"],
                capture_output=True, text=True, timeout=10,
            )
            result["version"] = ver.stdout.strip()[:200]
        except Exception as e:
            result["version"] = f"error: {e}"
    else:
        result["error"] = "hipcc not found in PATH"
    return result


def _probe_torch_arch() -> dict:
    """Test torch CUDA/ROCm arch support."""
    result = {
        "cuda_available": torch.cuda.is_available(),
        "device_name": None,
        "arch_list": None,
        "rocm_version": None,
    }
    if torch.cuda.is_available():
        result["device_name"] = torch.cuda.get_device_name(0)
        try:
            result["arch_list"] = torch.cuda.get_arch_list()
        except Exception:
            result["arch_list"] = "unavailable"
    try:
        result["rocm_version"] = torch.version.hip
    except AttributeError:
        result["rocm_version"] = "not ROCm build"
    return result


def _probe_env() -> dict:
    """Check relevant environment variables."""
    keys = [
        "ROCM_HOME", "ROCM_PATH", "HIP_PATH", "HSA_OVERRIDE_GFX_VERSION",
        "HIPRTC_COMPILE_OPTIONS_APPEND", "HIP_VISIBLE_DEVICES",
        "CUDA_VISIBLE_DEVICES", "GPU_DEVICE_ORDINAL",
    ]
    return {k: os.environ.get(k, "NOT SET") for k in keys}


def _probe_shared_libs() -> dict:
    """Check which HIP-related shared libraries exist."""
    search_dirs = [
        "/opt/rocm/lib", "/usr/lib", "/usr/lib64",
        "/opt/rocm/hip/lib", "/usr/local/lib",
    ]
    target_libs = [
        "libhiprtc.so", "libamdhip64.so", "libhsa-runtime64.so",
        "libamd_comgr.so", "librocblas.so",
    ]
    found = {}
    for lib in target_libs:
        paths = []
        for d in search_dirs:
            candidate = os.path.join(d, lib)
            if os.path.exists(candidate):
                paths.append(candidate)
        # Also check ldconfig
        try:
            ld = subprocess.run(
                ["ldconfig", "-p"],
                capture_output=True, text=True, timeout=5,
            )
            for line in ld.stdout.splitlines():
                if lib in line and "=>" in line:
                    path = line.split("=>")[-1].strip()
                    if path not in paths:
                        paths.append(path)
        except Exception:
            pass
        found[lib] = paths if paths else ["NOT FOUND"]
    return found


def custom_kernel(data: input_t) -> output_t:
    """Run environment probes then delegate to ref_kernel."""
    print("\n" + "=" * 70)
    print("HIPRTC ENVIRONMENT PROBE — Phase A")
    print("=" * 70)

    probes = {
        "hip_python": _probe_hip_python,
        "ctypes_hiprtc": _probe_ctypes_hiprtc,
        "hipcc": _probe_hipcc,
        "torch_arch": _probe_torch_arch,
        "env_vars": _probe_env,
        "shared_libs": _probe_shared_libs,
    }

    results = {}
    for name, probe_fn in probes.items():
        print(f"\n--- {name} ---")
        try:
            result = probe_fn()
            results[name] = result
            for k, v in result.items():
                print(f"  {k}: {v}")
        except Exception as e:
            print(f"  PROBE FAILED: {e}")
            results[name] = {"error": str(e)}

    # Summary
    print("\n" + "=" * 70)
    print("SUMMARY")
    print("=" * 70)

    hip_py = results.get("hip_python", {}).get("available", False)
    ctypes_ok = (
        results.get("ctypes_hiprtc", {}).get("hiprtc_available", False)
        and results.get("ctypes_hiprtc", {}).get("amdhip64_available", False)
    )
    compile_ok = "SUCCESS" in str(results.get("ctypes_hiprtc", {}).get("compile_test", ""))
    hipcc_ok = results.get("hipcc", {}).get("available", False)

    print(f"  hip-python available:    {'YES' if hip_py else 'NO'}")
    print(f"  ctypes hiprtc available: {'YES' if ctypes_ok else 'NO'}")
    print(f"  gfx950 compile test:     {'PASS' if compile_ok else 'FAIL'}")
    print(f"  hipcc available:         {'YES' if hipcc_ok else 'NO'}")

    if compile_ok:
        print("\n  >>> DECISION: hiprtc path AVAILABLE — proceed to Phase B")
    elif ctypes_ok:
        print("\n  >>> DECISION: hiprtc libs found but compile failed — investigate arch flag")
    elif hipcc_ok:
        print("\n  >>> DECISION: hipcc available as fallback — use subprocess compilation")
    else:
        print("\n  >>> DECISION: No hiprtc path — fall back to parameter tuning only")

    print("=" * 70 + "\n")

    # Delegate to reference kernel for correctness
    return ref_kernel(data)

