                dot += a_val * b_val;
            }

            acc[e] += dot;
        }
    }

    // Write output
    for (int e = 0; e < elems_per_thread; e++) {
        int flat_idx = tid + e * BLOCK_SIZE;
        int local_m = flat_idx / TILE_N;
        int local_n = flat_idx % TILE_N;
        int global_m = row_start + local_m;
        int global_n = col_start + local_n;

        if (global_m < M && global_n < N) {
            C[(long long)global_m * N + global_n] = __float2bfloat16(acc[e]);
        }
    }
}
'''

# ─── Fallback: two-kernel pipeline ──────────────────────────────────────


def _two_kernel_fallback(data: input_t) -> output_t:
    """Current best: dynamic_mxfp4_quant + gemm_a4w4."""
    from aiter import dtypes
    import aiter
    from aiter.ops.triton.quant import dynamic_mxfp4_quant
    from aiter.utility.fp4_utils import e8m0_shuffle

    A, B, B_q, B_shuffle, B_scale_sh = data
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    return aiter.gemm_a4w4(
        A_q, B_shuffle, A_scale_sh, B_scale_sh,
        dtype=dtypes.bf16, bpreshuffle=True,
    )


# ─── Submission entry point ─────────────────────────────────────────────

_hiprtc_ready = None


def _ensure_compiled():
    global _gemm_module, _gemm_func, _hiprtc_ready

    if _hiprtc_ready is not None:
        return _hiprtc_ready

    try:
        if not _load_hip_libs():
            print("[GEMM-hiprtc] hiprtc not available, using two-kernel fallback")
            _hiprtc_ready = False
            return False

        _gemm_module, _gemm_func = _compile_kernel(
            FUSED_GEMM_SOURCE, "fused_mxfp4_gemm",
        )
        _hiprtc_ready = True
        print("[GEMM-hiprtc] Fused kernel compiled successfully for gfx950")
        return True

    except Exception as e:
        print(f"[GEMM-hiprtc] Compilation failed: {e}")
        _hiprtc_ready = False
        return False


def custom_kernel(data: input_t) -> output_t:
    """Fused MXFP4 quant + GEMM via hiprtc with two-kernel fallback."""
    A, B, B_q, B_shuffle, B_scale_sh = data

    if not _ensure_compiled():
        return _two_kernel_fallback(data)

    M, K = A.shape
    N = B.shape[0]

    # Allocate output
    C = torch.empty((M, N), dtype=torch.bfloat16, device="cuda")

    # B_q is pre-quantized fp4x2 [N, K/2]
    # B_scale_sh is shuffled E8M0 scales
    # For the naive hiprtc kernel, we need unshuffled B and scales
    # NOTE: The naive kernel uses B_q directly (not shuffled) and
    # B_scale from the original quantization.
    # For the hiprtc path, we re-quantize B to get unshuffled format.
    # This is a correctness-first approach — the local model will
    # optimize to use pre-shuffled formats matching MFMA tile layout.

    # Use B_q (unshuffled) and compute scales from B
    from aiter import QuantType
    import aiter
    quant_func = aiter.get_triton_quant(QuantType.per_1x32)
    B_q_unshuffle, B_scale_unshuffle = quant_func(B, shuffle=False)

    # Get raw bytes for ctypes
    B_q_bytes = B_q_unshuffle.view(torch.uint8)
    B_scale_bytes = B_scale_unshuffle.view(torch.uint8)

    N_pad = B_scale_bytes.shape[0]

    # Grid: (ceil(M/64), ceil(N/64))
    grid_m = (M + 63) // 64
    grid_n = (N + 63) // 64

    _launch(
        _gemm_func,
        (grid_m, grid_n, 1), (256, 1, 1),
        0,  # shared memory (naive version uses none)
        ctypes.c_void_p(C.data_ptr()),
        ctypes.c_void_p(A.data_ptr()),
        ctypes.c_void_p(B_q_bytes.data_ptr()),
        ctypes.c_void_p(B_scale_bytes.data_ptr()),
        ctypes.c_int(M),
        ctypes.c_int(N),
        ctypes.c_int(K),
        ctypes.c_int(N_pad),
    )

    return C

