def _compile_kernel(source: str, kernel_name: str, arch: str = "gfx950"):
    prog = ctypes.c_void_p()
    rc = _hiprtc_lib.hiprtcCreateProgram(
        ctypes.byref(prog), source.encode(), b"mla.hip", 0, None, None,
    )
    if rc != 0:
        raise RuntimeError(f"hiprtcCreateProgram failed: rc={rc}")

    opts = [f"--gpu-architecture={arch}".encode()]
    opts_arr = (ctypes.c_char_p * len(opts))(*opts)
    rc = _hiprtc_lib.hiprtcCompileProgram(prog, len(opts), opts_arr)
    if rc != 0:
        log_size = ctypes.c_size_t()
        _hiprtc_lib.hiprtcGetProgramLogSize(prog, ctypes.byref(log_size))
        log = ctypes.create_string_buffer(log_size.value)
        _hiprtc_lib.hiprtcGetProgramLog(prog, log)
        _hiprtc_lib.hiprtcDestroyProgram(ctypes.byref(prog))
        raise RuntimeError(f"Compile failed:\n{log.value.decode()}")

    code_size = ctypes.c_size_t()
    _hiprtc_lib.hiprtcGetCodeSize(prog, ctypes.byref(code_size))
    code = ctypes.create_string_buffer(code_size.value)
    _hiprtc_lib.hiprtcGetCode(prog, code)
    _hiprtc_lib.hiprtcDestroyProgram(ctypes.byref(prog))

    module = ctypes.c_void_p()
    rc = _hip_lib.hipModuleLoadData(ctypes.byref(module), code)
    if rc != 0:
        raise RuntimeError(f"hipModuleLoadData failed: rc={rc}")

    func = ctypes.c_void_p()
    rc = _hip_lib.hipModuleGetFunction(
        ctypes.byref(func), module, kernel_name.encode(),
    )
    if rc != 0:
        raise RuntimeError(f"hipModuleGetFunction({kernel_name}) failed: rc={rc}")

    return module, func


def _launch(func, grid, block, shared_mem, *args):
    arg_ptrs = []
    for a in args:
        arg_ptrs.append(ctypes.cast(ctypes.pointer(a), ctypes.c_void_p))
    args_arr = (ctypes.c_void_p * len(arg_ptrs))(*arg_ptrs)
    rc = _hip_lib.hipModuleLaunchKernel(
        func, grid[0], grid[1], grid[2],
        block[0], block[1], block[2],
        shared_mem, None, args_arr, None,
    )
    if rc != 0:
        raise RuntimeError(f"hipModuleLaunchKernel failed: rc={rc}")


# ─── MLA Decode Kernel (C1: naive bf16 with online softmax) ─────────────

MLA_KERNEL_SOURCE = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

/*
 * MLA Decode: Q[total_q, nheads, 576] @ KV[total_kv, 1, 576]^T -> softmax -> @V[:,:512]
 *
 * Grid:  (batch_size, nheads, 1)
 * Block: (BLOCK_SIZE, 1, 1)  where BLOCK_SIZE=256
 *
 * Each block handles one (batch, head) pair.
 * Threads cooperatively iterate over the KV sequence.
 * Online softmax: single pass computing running max + denominator.
 *
 * Memory layout:
 *   Q:   row-major [total_q, nheads, QK_DIM]  bf16
 *   KV:  row-major [total_kv, 1, QK_DIM]      bf16
 *   Out: row-major [total_q, nheads, V_DIM]    bf16
 */

#define QK_DIM 576
#define V_DIM 512
#define BLOCK_SIZE 256

extern "C" __global__
void mla_decode_bf16(
    __hip_bfloat16* __restrict__ out,       // [total_q, nheads, V_DIM]
    const __hip_bfloat16* __restrict__ q,   // [total_q, nheads, QK_DIM]
    const __hip_bfloat16* __restrict__ kv,  // [total_kv, 1, QK_DIM]
    const int* __restrict__ qo_indptr,      // [bs+1]
    const int* __restrict__ kv_indptr,      // [bs+1]
    int nheads,
    float sm_scale
) {
    int batch_idx = blockIdx.x;
    int head_idx  = blockIdx.y;
    int tid = threadIdx.x;

    // Compute sequence boundaries
    int q_start = qo_indptr[batch_idx];
    int kv_start = kv_indptr[batch_idx];
    int kv_end   = kv_indptr[batch_idx + 1];
    int kv_len   = kv_end - kv_start;

    // For decode: qseqlen=1, so q_idx = q_start
    int q_idx = q_start;

    // Load Q vector for this head into registers
    // Each thread loads QK_DIM/BLOCK_SIZE elements
    const int q_elements_per_thread = (QK_DIM + BLOCK_SIZE - 1) / BLOCK_SIZE;
    float q_local[3];  // ceil(576/256) = 3
    const __hip_bfloat16* q_row = q + (long long)q_idx * nheads * QK_DIM
                                    + (long long)head_idx * QK_DIM;

    for (int i = 0; i < q_elements_per_thread; i++) {
        int col = tid + i * BLOCK_SIZE;
        q_local[i] = (col < QK_DIM) ? __bfloat162float(q_row[col]) : 0.0f;
    }

    // Online softmax accumulators (per thread)
    float thread_max = -1e20f;
    float thread_sum = 0.0f;

    // Value accumulator: each thread accumulates V_DIM/BLOCK_SIZE elements
    const int v_elements_per_thread = (V_DIM + BLOCK_SIZE - 1) / BLOCK_SIZE;
    float v_acc[2];  // ceil(512/256) = 2
    for (int i = 0; i < v_elements_per_thread; i++) v_acc[i] = 0.0f;

    // Shared memory for broadcasting dot product results
    __shared__ float s_score[1];  // broadcast single score

    // Iterate over KV sequence
    for (int kv_pos = 0; kv_pos < kv_len; kv_pos++) {
        const __hip_bfloat16* kv_row = kv + (long long)(kv_start + kv_pos) * QK_DIM;

        // Step 1: Compute Q @ K^T (dot product) — parallel reduction
        float dot = 0.0f;
        for (int i = 0; i < q_elements_per_thread; i++) {
            int col = tid + i * BLOCK_SIZE;
            if (col < QK_DIM) {
                float kv_val = __bfloat162float(kv_row[col]);
                dot += q_local[i] * kv_val;
            }
        }

        // Warp-level reduction for dot product
        for (int offset = 32; offset > 0; offset >>= 1) {
            dot += __shfl_down(dot, offset);
        }

        // Cross-warp reduction via shared memory
        __shared__ float s_partial[BLOCK_SIZE / 64];
        if ((tid & 63) == 0) {
            s_partial[tid / 64] = dot;
        }
        __syncthreads();

        // Final reduction by thread 0
        if (tid == 0) {
            float total = 0.0f;
            for (int w = 0; w < BLOCK_SIZE / 64; w++) {
                total += s_partial[w];
            }
            s_score[0] = total * sm_scale;
        }
        __syncthreads();

        float score = s_score[0];

        // Step 2: Online softmax update
        float old_max = thread_max;
        float new_max = fmaxf(old_max, score);
        float exp_score = expf(score - new_max);
        float correction = expf(old_max - new_max);

        thread_sum = thread_sum * correction + exp_score;
        thread_max = new_max;

        // Step 3: Accumulate value (with online softmax correction)
        for (int i = 0; i < v_elements_per_thread; i++) {
            int col = tid + i * BLOCK_SIZE;
            if (col < V_DIM) {
                float v_val = __bfloat162float(kv_row[col]);
                v_acc[i] = v_acc[i] * correction + exp_score * v_val;
            }
        }
    }

    // Normalize by softmax denominator and write output
    __hip_bfloat16* out_row = out + (long long)q_idx * nheads * V_DIM
                                  + (long long)head_idx * V_DIM;

    float inv_sum = (thread_sum > 0.0f) ? (1.0f / thread_sum) : 0.0f;
    for (int i = 0; i < v_elements_per_thread; i++) {
        int col = tid + i * BLOCK_SIZE;
        if (col < V_DIM) {
            out_row[col] = __float2bfloat16(v_acc[i] * inv_sum);
        }
    }
}
'''

# ─── Fallback: aiter-based MLA ──────────────────────────────────────────

_aiter_available = True


