    o = torch.empty(
        (q.shape[0], nheads, V_HEAD_DIM),
        dtype=torch.bfloat16, device="cuda",
    )

    mla_decode_fwd(
        q_input.view(-1, nheads, QK_HEAD_DIM), kv_4d, o,
        qo_indptr, kv_indptr, kv_indices, kv_last_page_len,
        qseqlen, page_size=1, nhead_kv=1,
        sm_scale=SM_SCALE, logit_cap=0.0, num_kv_splits=32,
        q_scale=q_scale, kv_scale=kv_scale,
        intra_batch_mode=True,
        work_meta_data=wm, work_indptr=wi, work_info_set=wis,
        reduce_indptr=ri, reduce_final_map=rfm, reduce_partial_map=rpm,
    )
    return o


# ─── Submission entry point ─────────────────────────────────────────────

_hiprtc_ready = None


def _ensure_compiled():
    """Compile MLA kernel once, cache for subsequent calls."""
    global _mla_module, _mla_func, _hiprtc_ready

    if _hiprtc_ready is not None:
        return _hiprtc_ready

    try:
        if not _load_hip_libs():
            print("[MLA-hiprtc] hiprtc not available, using aiter fallback")
            _hiprtc_ready = False
            return False

        _mla_module, _mla_func = _compile_kernel(MLA_KERNEL_SOURCE, "mla_decode_bf16")
        _hiprtc_ready = True
        print("[MLA-hiprtc] Kernel compiled successfully for gfx950")
        return True

    except Exception as e:
        print(f"[MLA-hiprtc] Compilation failed: {e}")
        _hiprtc_ready = False
        return False


def custom_kernel(data: input_t) -> output_t:
    """MLA decode via hiprtc (Phase C) with aiter fallback."""
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    nheads = config["num_heads"]
    kvseqlen = config["kv_seq_len"]

    if not _ensure_compiled():
        return _aiter_fallback(data)

    # Use bf16 KV for the hiprtc kernel (C1: naive bf16)
    kv_bf16 = kv_data["bf16"]

    # Allocate output
    o = torch.empty(
        (q.shape[0], nheads, V_HEAD_DIM),
        dtype=torch.bfloat16, device="cuda",
    )

    # Launch: grid=(bs, nheads), block=(256)
    _launch(
        _mla_func,
        (bs, nheads, 1), (256, 1, 1),
        4 * (256 // 64 + 1),  # shared memory for partial sums + score
        ctypes.c_void_p(o.data_ptr()),
        ctypes.c_void_p(q.data_ptr()),
        ctypes.c_void_p(kv_bf16.data_ptr()),
        ctypes.c_void_p(qo_indptr.data_ptr()),
        ctypes.c_void_p(kv_indptr.data_ptr()),
        ctypes.c_int(nheads),
        ctypes.c_float(SM_SCALE),
    )

    return o

"""
Phase D: Fused MXFP4 quant + GEMM via hiprtc.

Fuses dynamic_mxfp4_quant + gemm_a4w4 into a single hiprtc kernel to
eliminate the two-kernel launch overhead (~10 us). The kernel:
  1. Quantizes A tiles to MXFP4 on-the-fly in shared memory
  2. Loads pre-shuffled B tiles (already in MXFP4)
  3. Computes GEMM using MFMA intrinsics

Falls back to the current two-kernel pipeline if hiprtc is unavailable.

TEMPLATE for local model iteration — Claude writes spec, local model
generates the optimized HIP C++ kernel body.
"""
import ctypes
import torch
from task import input_t, output_t

# ─── hiprtc infrastructure (shared with MLA kernel) ─────────────────────

_hiprtc_lib = None
_hip_lib = None
_gemm_module = None
_gemm_func = None


def _load_hip_libs():
    global _hiprtc_lib, _hip_lib
    if _hiprtc_lib is not None:
        return True
    for name in ["libhiprtc.so", "libhiprtc.so.6", "libhiprtc.so.5"]:
        try:
            _hiprtc_lib = ctypes.CDLL(name)
            break
        except OSError:
            continue
    for name in ["libamdhip64.so", "libamdhip64.so.6", "libamdhip64.so.5"]:
        try:
            _hip_lib = ctypes.CDLL(name)
            break
        except OSError:
            continue
    return _hiprtc_lib is not None and _hip_lib is not None


def _compile_kernel(source: str, kernel_name: str, arch: str = "gfx950"):
    prog = ctypes.c_void_p()
    rc = _hiprtc_lib.hiprtcCreateProgram(
        ctypes.byref(prog), source.encode(), b"gemm.hip", 0, None, None,
    )
    if rc != 0:
        raise RuntimeError(f"hiprtcCreateProgram failed: rc={rc}")

    opts = [f"--gpu-architecture={arch}".encode()]
    opts_arr = (ctypes.c_char_p * len(opts))(*opts)
    rc = _hiprtc_lib.hiprtcCompileProgram(prog, len(opts), opts_arr)
    if rc != 0:
        log_size = ctypes.c_size_t()
        _hiprtc_lib.hiprtcGetProgramLogSize(prog, ctypes.byref(log_size))
        log = ctypes.create_string_buffer(log_size.value)
        _hiprtc_lib.hiprtcGetProgramLog(prog, log)
        _hiprtc_lib.hiprtcDestroyProgram(ctypes.byref(prog))
        raise RuntimeError(f"Compile failed:\n{log.value.decode()}")

    code_size = ctypes.c_size_t()
    _hiprtc_lib.hiprtcGetCodeSize(prog, ctypes.byref(code_size))
    code = ctypes.create_string_buffer(code_size.value)
    _hiprtc_lib.hiprtcGetCode(prog, code)
    _hiprtc_lib.hiprtcDestroyProgram(ctypes.byref(prog))

    module = ctypes.c_void_p()
    rc = _hip_lib.hipModuleLoadData(ctypes.byref(module), code)
    if rc != 0:
        raise RuntimeError(f"hipModuleLoadData failed: rc={rc}")

    func = ctypes.c_void_p()
    rc = _hip_lib.hipModuleGetFunction(
        ctypes.byref(func), module, kernel_name.encode(),
    )
    if rc != 0:
        raise RuntimeError(f"hipModuleGetFunction({kernel_name}) failed: rc={rc}")

    return module, func


def _launch(func, grid, block, shared_mem, *args):
    arg_ptrs = []
    for a in args:
        arg_ptrs.append(ctypes.cast(ctypes.pointer(a), ctypes.c_void_p))
    args_arr = (ctypes.c_void_p * len(arg_ptrs))(*arg_ptrs)
    rc = _hip_lib.hipModuleLaunchKernel(
        func, grid[0], grid[1], grid[2],
        block[0], block[1], block[2],
        shared_mem, None, args_arr, None,
    )
    if rc != 0:
        raise RuntimeError(f"hipModuleLaunchKernel failed: rc={rc}")


# ─── Fused MXFP4 Quant + GEMM kernel ───────────────────────────────────

FUSED_GEMM_SOURCE = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

/*
 * Fused MXFP4 Quant + GEMM
 *
 * A [M, K] bf16 — quantized on-the-fly to MXFP4
 * B [N, K] pre-quantized MXFP4 (shuffled, fp4x2 format)
 * B_scale [N_padded, K/32] E8M0 block scales (shuffled)
 * C [M, N] bf16 output
 *
 * Algorithm per tile (TILE_M x TILE_N):
 *   for each K-tile of size TILE_K:
 *     1. Load A tile [TILE_M, TILE_K] bf16 into shared memory
 *     2. Quantize A tile to MXFP4 in shared memory (block-32 E8M0)
 *     3. Load B tile [TILE_N, TILE_K] MXFP4 (pre-quantized)
 *     4. Dequantize both to f32 and compute MFMA outer product
 *     5. Accumulate in f32 registers
 *   Write C tile as bf16
 *
 * Grid:  (ceil(M/TILE_M), ceil(N/TILE_N), 1)
 * Block: (256, 1, 1)
 *
 * MXFP4 format: 2 FP4 (E2M1) values packed per byte
 * E8M0 scale: 1 scale per 32 elements (exponent only, no mantissa)
 *
 * NOTE: This is a NAIVE implementation for correctness validation.
 * The local finetuned model should iterate on:
 *   - MFMA intrinsics (mfma_f32_16x16x16_bf16 or mfma_f32_32x32x64_fp4)
 *   - LDS bank conflict avoidance
 *   - Double buffering for A/B tile loads
 *   - Optimal TILE_M/TILE_N/TILE_K for MI355X occupancy
 */

#define TILE_M 64
#define TILE_N 64
#define TILE_K 32
#define BLOCK_SIZE 256
#define SCALE_GROUP 32

// FP4 E2M1 lookup table (4-bit index -> float value)
__device__ __constant__ float fp4_lut[16] = {
    0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f,
    -0.0f, -0.5f, -1.0f, -1.5f, -2.0f, -3.0f, -4.0f, -6.0f
};

// E8M0 to float: scale = 2^(e8m0_val - 127)
__device__ float e8m0_to_float(unsigned char e) {
    int exp_val = (int)e - 127;
    // Use ldexpf for exact power-of-2
    return ldexpf(1.0f, exp_val);
}

// Dynamic MXFP4 quantize a block of 32 bf16 values
// Returns packed fp4x2 (16 bytes) and E8M0 scale (1 byte)
__device__ void quant_block_mxfp4(
    const __hip_bfloat16* src,  // 32 bf16 values
    unsigned char* dst_fp4,     // 16 bytes output (32 fp4 packed)
    unsigned char* dst_scale    // 1 byte E8M0 scale
) {
    // Find max absolute value in block
    float amax = 0.0f;
    float vals[32];
    for (int i = 0; i < 32; i++) {
        vals[i] = __bfloat162float(src[i]);
        float av = fabsf(vals[i]);
        amax = fmaxf(amax, av);
    }

    // Compute E8M0 scale: find exponent such that max maps to FP4 range [0,6]
    int exp_val;
    if (amax < 1e-30f) {
        exp_val = 0;
    } else {
        // FP4 E2M1 max = 6.0, so scale = amax / 6.0
        // E8M0 = floor(log2(scale)) + 127
        float scale = amax / 6.0f;
        int e = 0;
        frexpf(scale, &e);  // e = exponent
        exp_val = e + 127 - 1;
        if (exp_val < 0) exp_val = 0;
        if (exp_val > 255) exp_val = 255;
    }
    *dst_scale = (unsigned char)exp_val;
    float inv_scale = 1.0f / ldexpf(1.0f, exp_val - 127);

    // Quantize each value to FP4 E2M1 and pack pairs
    for (int i = 0; i < 16; i++) {
        float v0 = vals[2*i] * inv_scale;
        float v1 = vals[2*i+1] * inv_scale;

        // Clamp and round to nearest FP4 value
        // FP4 E2M1: {0, 0.5, 1, 1.5, 2, 3, 4, 6} x {+,-}
        auto quantize_fp4 = [](float v) -> unsigned char {
            int sign = (v < 0.0f) ? 8 : 0;
            float av = fabsf(v);
            unsigned char idx;
            if (av < 0.25f) idx = 0;
            else if (av < 0.75f) idx = 1;
            else if (av < 1.25f) idx = 2;
            else if (av < 1.75f) idx = 3;
            else if (av < 2.5f) idx = 4;
            else if (av < 3.5f) idx = 5;
            else if (av < 5.0f) idx = 6;
            else idx = 7;
            return (unsigned char)(sign | idx);
        };

        unsigned char q0 = quantize_fp4(v0);
        unsigned char q1 = quantize_fp4(v1);
        dst_fp4[i] = (q1 << 4) | q0;  // pack two fp4 into one byte
    }
}

extern "C" __global__
void fused_mxfp4_gemm(
    __hip_bfloat16* __restrict__ C,          // [M, N] output
    const __hip_bfloat16* __restrict__ A,    // [M, K] input
    const unsigned char* __restrict__ B_q,   // [N, K/2] pre-quantized fp4x2
    const unsigned char* __restrict__ B_scale, // [N_pad, K/32] E8M0 scales
    int M, int N, int K,
    int N_pad  // padded N for B_scale stride
) {
    int tile_m = blockIdx.x;
    int tile_n = blockIdx.y;
    int tid = threadIdx.x;

    int row_start = tile_m * TILE_M;
    int col_start = tile_n * TILE_N;

    // Each thread accumulates a subset of the TILE_M x TILE_N output
    // Thread layout: TILE_M * TILE_N / BLOCK_SIZE elements per thread
    const int elems_per_thread = (TILE_M * TILE_N) / BLOCK_SIZE;  // 64*64/256 = 16
    float acc[16];
    for (int i = 0; i < 16; i++) acc[i] = 0.0f;

    // Iterate over K dimension in TILE_K chunks
    for (int k_tile = 0; k_tile < K; k_tile += TILE_K) {
        // Each thread loads and processes elements
        for (int e = 0; e < elems_per_thread; e++) {
            int flat_idx = tid + e * BLOCK_SIZE;
            int local_m = flat_idx / TILE_N;
            int local_n = flat_idx % TILE_N;
            int global_m = row_start + local_m;
            int global_n = col_start + local_n;

            if (global_m >= M || global_n >= N) continue;

            float dot = 0.0f;
            for (int dk = 0; dk < TILE_K && (k_tile + dk) < K; dk++) {
                int global_k = k_tile + dk;

                // A value (bf16)
                float a_val = __bfloat162float(
                    A[(long long)global_m * K + global_k]
                );

                // B value (dequantize from MXFP4)
                int b_byte_idx = global_n * (K / 2) + global_k / 2;
                unsigned char b_packed = B_q[b_byte_idx];
                unsigned char b_nibble;
                if (global_k % 2 == 0) {
                    b_nibble = b_packed & 0x0F;
                } else {
                    b_nibble = (b_packed >> 4) & 0x0F;
                }
                float b_val = fp4_lut[b_nibble];

                // B scale (E8M0)
                int scale_idx = global_n * (K / SCALE_GROUP) + global_k / SCALE_GROUP;
                // Use N_pad stride for scale array
                int scale_row = global_n;
                int scale_col = global_k / SCALE_GROUP;
                unsigned char b_e8m0 = B_scale[
                    (long long)scale_row * (K / SCALE_GROUP) + scale_col
                ];
                float b_scale_val = e8m0_to_float(b_e8m0);
                b_val *= b_scale_val;

                dot += a_val * b_val;
            }

            acc[e] += dot;
        }
    }

    // Write output
    for (int e = 0; e < elems_per_thread; e++) {
        int flat_idx = tid + e * BLOCK_SIZE;
        int local_m = flat_idx / TILE_N;
        int local_n = flat_idx % TILE_N;
        int global_m = row_start + local_m;
        int global_n = col_start + local_n;

        if (global_m < M && global_n < N) {
            C[(long long)global_m * N + global_n] = __float2bfloat16(acc[e]);
        }
    }
}
'''

# ─── Fallback: two-kernel pipeline ──────────────────────────────────────


def _two_kernel_fallback(data: input_t) -> output_t:
    """Current best: dynamic_mxfp4_quant + gemm_a4w4."""
    from aiter import dtypes
    import aiter
    from aiter.ops.triton.quant import dynamic_mxfp4_quant
    from aiter.utility.fp4_utils import e8m0_shuffle

    A, B, B_q, B_shuffle, B_scale_sh = data
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    return aiter.gemm_a4w4(
        A_q, B_shuffle, A_scale_sh, B_scale_sh,
        dtype=dtypes.bf16, bpreshuffle=True,
    )


# ─── Submission entry point ─────────────────────────────────────────────

_hiprtc_ready = None


def _ensure_compiled():
    global _gemm_module, _gemm_func, _hiprtc_ready

    if _hiprtc_ready is not None:
        return _hiprtc_ready

    try:
        if not _load_hip_libs():
            print("[GEMM-hiprtc] hiprtc not available, using two-kernel fallback")
            _hiprtc_ready = False
            return False

        _gemm_module, _gemm_func = _compile_kernel(
            FUSED_GEMM_SOURCE, "fused_mxfp4_gemm",
        )
        _hiprtc_ready = True
        print("[GEMM-hiprtc] Fused kernel compiled successfully for gfx950")
        return True

    except Exception as e:
        print(f"[GEMM-hiprtc] Compilation failed: {e}")
        _hiprtc_ready = False
        return False


def custom_kernel(data: input_t) -> output_t:
    """Fused MXFP4 quant + GEMM via hiprtc with two-kernel fallback."""
    A, B, B_q, B_shuffle, B_scale_sh = data

    if not _ensure_compiled():
        return _two_kernel_fallback(data)

    M, K = A.shape
    N = B.shape[0]

    # Allocate output
    C = torch.empty((M, N), dtype=torch.bfloat16, device="cuda")

    # B_q is pre-quantized fp4x2 [N, K/2]
    # B_scale_sh is shuffled E8M0 scales
    # For the naive hiprtc kernel, we need unshuffled B and scales
    # NOTE: The naive kernel uses B_q directly (not shuffled) and
    # B_scale from the original quantization.
    # For the hiprtc path, we re-quantize B to get unshuffled format.
    # This is a correctness-first approach — the local model will
    # optimize to use pre-shuffled formats matching MFMA tile layout.

    # Use B_q (unshuffled) and compute scales from B
    from aiter import QuantType
    import aiter
    quant_func = aiter.get_triton_quant(QuantType.per_1x32)
    B_q_unshuffle, B_scale_unshuffle = quant_func(B, shuffle=False)

    # Get raw bytes for ctypes
    B_q_bytes = B_q_unshuffle.view(torch.uint8)
    B_scale_bytes = B_scale_unshuffle.view(torch.uint8)

    N_pad = B_scale_bytes.shape[0]

    # Grid: (ceil(M/64), ceil(N/64))
    grid_m = (M + 63) // 64
    grid_n = (N + 63) // 64

    _launch(
        _gemm_func,
        (grid_m, grid_n, 1), (256, 1, 1),
        0,  # shared memory (naive version uses none)
        ctypes.c_void_p(C.data_ptr()),
        ctypes.c_void_p(A.data_ptr()),
        ctypes.c_void_p(B_q_bytes.data_ptr()),
        ctypes.c_void_p(B_scale_bytes.data_ptr()),
        ctypes.c_int(M),
        ctypes.c_int(N),
        ctypes.c_int(K),
        ctypes.c_int(N_pad),
    )

    return C
